1	// Shared plumbing for this pack's checks.
2	//
3	// Deliberately dependency-free, and deliberately NOT importing the sibling
4	// browser-speech pack's copy of the same helpers: a pack composes by declaration,
5	// never by importing another pack's code (pack independence), and a local pack's
6	// check modules must load even when the gitignored canon mount is absent — the
7	// project's own vitest run is exactly that situation.
8	
9	/** The plain finding object the checks runner consumes (engine/checks/README.md). */
10	export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
11	  return {
12	    rule: rule.id,
13	    severity: severity || rule.severity,
14	    file,
15	    line,
16	    what,
17	    why: why || rule.why,
18	    fix,
19	    doc: rule.doc,
20	  };
21	}
22	
23	// String-aware comment stripper. Every rule here matches against source *code*: a
24	// comment that merely names `dispatchEvent` or `MutationObserver` describes the
25	// trap, it doesn't spring it — and this pack's own prose would otherwise fire its
26	// own checks. Newlines are preserved so line numbers survive the strip.
27	export function stripComments(source) {
28	  let out = '';
29	  let state = 'code'; // code | line | block | sq | dq | tpl
30	  for (let i = 0; i < source.length; i++) {
31	    const c = source[i];
32	    const c2 = source[i + 1];
33	    if (state === 'code') {
34	      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
35	      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
36	      if (c === "'") state = 'sq';
37	      else if (c === '"') state = 'dq';
38	      else if (c === '`') state = 'tpl';
39	      out += c;
40	    } else if (state === 'line') {
41	      if (c === '\n') { state = 'code'; out += c; }
42	    } else if (state === 'block') {
43	      if (c === '*' && c2 === '/') { state = 'code'; i++; }
44	      else if (c === '\n') out += c;
45	    } else {
46	      out += c;
47	      if (c === '\\') { out += c2 ?? ''; i++; }
48	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
49	        state = 'code';
50	      }
51	    }
52	  }
53	  return out;
54	}
55	
56	// What counts as shipped browser source. Deliberately NOT a hard-coded project
57	// root: every rule in this pack is gated on the DOM API it judges actually
58	// appearing in the file, so the trigger is the API usage itself and the scan can
59	// safely be repo-shaped. A path scope hard-wired to one project's layout would
60	// make every rule match zero files — and pass VACUOUSLY GREEN — in any repo laid
61	// out differently, which is the worst failure mode a check has.
62	//
63	// The one thing the scan must still exclude is test scaffolding: a test that
64	// dispatches a bare event at its own jsdom node, or spins an observer it lets the
65	// test runner collect, is doing something purpose-built and is not adapting to a
66	// host page. That exclusion is expressed directly — by test/vendor path and test
67	// filename — instead of being a side effect of the source root.
68	const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
69	const NOT_SOURCE = [
70	  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
71	  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
72	  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
