93	        if (src[i] === quote) break;
94	      }
95	      continue;
96	    }
97	    if (c === '{' || c === '[' || c === '(') depth += 1;
98	    else if (c === '}' || c === ']' || c === ')') {
99	      depth -= 1;
100	      if (depth === 0) return src.slice(open, i + 1);
101	    }
102	  }
103	  return null;
104	}
